{
  "name": "HAYTI - Supérettes de Quartier",
  "description": "Une plateforme digitale mettant en relation les consommateurs d'un même quartier avec les supérettes de proximité pour encourager la consommation locale.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

export enum UserRole {
  CLIENT = 'CLIENT',
  STORE = 'STORE',
  ADMIN = 'ADMIN'
}

export enum ProductOrigin {
  LOCAL = 'LOCAL',
  IMPORTED = 'IMPORTED'
}

export interface Product {
  id: string;
  name: string;
  price: number;
  origin: ProductOrigin;
  category: string;
  image: string;
  stock: number;
  storeId: string;
}

export interface Store {
  id: string;
  name: string;
  distance: string;
  rating: number;
  hours: string;
  image: string;
  neighborhood: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Order {
  id: string;
  date: string;
  total: number;
  status: 'PENDING' | 'PREPARING' | 'READY' | 'COMPLETED';
  items: CartItem[];
  pointsGained: number;
}

export interface UserProfile {
  name: string;
  email: string;
  points: number;
  role: UserRole;
  neighborhood?: string;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter } from 'react-router-dom';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <HashRouter>
      <App />
    </HashRouter>
  </React.StrictMode>
);

import React, { useState, useEffect, createContext, useContext } from 'react';
import { Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import { UserRole, UserProfile, CartItem, Product, Store, Order } from './types';
import { MOCK_STORES, MOCK_PRODUCTS } from './constants';

// Context for global state
interface AppContextType {
  user: UserProfile | null;
  setUser: (user: UserProfile | null) => void;
  cart: CartItem[];
  addToCart: (product: Product) => void;
  removeFromCart: (productId: string) => void;
  updateQuantity: (productId: string, delta: number) => void;
  clearCart: () => void;
  orders: Order[];
  placeOrder: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

// Pages (defined below)
import Splash from './pages/Splash';
import Onboarding from './pages/Onboarding';
import Login from './pages/Login';
import Home from './pages/Home';
import StoreList from './pages/StoreList';
import Catalog from './pages/Catalog';
import Cart from './pages/Cart';
import Fidelity from './pages/Fidelity';
import Profile from './pages/Profile';
import Dashboard from './pages/Dashboard';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const navigate = useNavigate();
  const location = useLocation();

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const clearCart = () => setCart([]);

  const placeOrder = () => {
    if (cart.length === 0) return;
    const total = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
    const points = Math.floor(total / 100);

    const newOrder: Order = {
      id: `ORD-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      date: new Date().toLocaleDateString('fr-FR'),
      total,
      status: 'PENDING',
      items: [...cart],
      pointsGained: points
    };

    setOrders(prev => [newOrder, ...prev]);
    if (user) {
      setUser({ ...user, points: user.points + points });
    }
    clearCart();
    navigate('/fidelity');
  };

  // Auth Guard & Redirects
  useEffect(() => {
    const publicPaths = ['/', '/onboarding', '/login'];
    if (!user && !publicPaths.includes(location.pathname)) {
      navigate('/login');
    }
    if (user && user.role === UserRole.STORE && location.pathname === '/home') {
      navigate('/dashboard');
    }
  }, [user, location.pathname, navigate]);

  return (
    <AppContext.Provider value={{
      user, setUser, cart, addToCart, removeFromCart, updateQuantity, clearCart, orders, placeOrder
    }}>
      <div className="max-w-md mx-auto min-h-screen bg-white shadow-xl relative overflow-hidden flex flex-col">
        <Routes>
          <Route path="/" element={<Splash />} />
          <Route path="/onboarding" element={<Onboarding />} />
          <Route path="/login" element={<Login />} />
          <Route path="/home" element={<Home />} />
          <Route path="/stores" element={<StoreList />} />
          <Route path="/store/:id" element={<Catalog />} />
          <Route path="/cart" element={<Cart />} />
          <Route path="/fidelity" element={<Fidelity />} />
          <Route path="/profile" element={<Profile />} />
          <Route path="/dashboard" element={<Dashboard />} />
        </Routes>
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import { 
  Home, 
  Store as StoreIcon, 
  ShoppingCart, 
  User, 
  ChevronLeft, 
  Search,
  MapPin,
  Gift
} from 'lucide-react';
import { useApp } from '../App';
import { UserRole } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  title?: string;
  showBack?: boolean;
  hideNav?: boolean;
}

const Layout: React.FC<LayoutProps> = ({ children, title, showBack = false, hideNav = false }) => {
  const { user, cart, setUser } = useApp();
  const location = useLocation();
  const navigate = useNavigate();

  const isClient = user?.role === UserRole.CLIENT;
  const isStore = user?.role === UserRole.STORE;

  const navItems = isClient ? [
    { label: 'Accueil', icon: Home, path: '/home' },
    { label: 'Boutiques', icon: StoreIcon, path: '/stores' },
    { label: 'Fidélité', icon: Gift, path: '/fidelity' },
    { label: 'Profil', icon: User, path: '/profile' },
  ] : [
    { label: 'Tableau', icon: Home, path: '/dashboard' },
    { label: 'Profil', icon: User, path: '/profile' },
  ];

  return (
    <div className="flex flex-col h-screen overflow-hidden">
      {/* Header */}
      <header className="bg-primary text-white p-4 sticky top-0 z-50 flex items-center justify-between shadow-md h-16 shrink-0">
        <div className="flex items-center space-x-2">
          {showBack && (
            <button onClick={() => navigate(-1)} className="p-1 hover:bg-primaryLight rounded-full transition-colors">
              <ChevronLeft size={24} />
            </button>
          )}
          <div>
            {title ? (
              <h1 className="font-semibold text-lg">{title}</h1>
            ) : (
              <div className="flex flex-col">
                <span className="text-xs opacity-80">Quartier</span>
                <div className="flex items-center text-sm font-semibold">
                  <MapPin size={14} className="mr-1" />
                  {user?.neighborhood || "Détecter..."}
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="flex items-center space-x-4">
          <button className="p-1"><Search size={22} /></button>
          {isClient && (
            <Link to="/cart" className="relative p-1">
              <ShoppingCart size={22} />
              {cart.length > 0 && (
                <span className="absolute -top-1 -right-1 bg-accent text-white text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full">
                  {cart.length}
                </span>
              )}
            </Link>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto no-scrollbar pb-20">
        {children}
      </main>

      {/* Bottom Navigation */}
      {!hideNav && (
        <nav className="bg-white border-t border-gray-200 h-16 sticky bottom-0 z-50 flex items-center justify-around px-2 shrink-0">
          {navItems.map((item) => {
            const isActive = location.pathname === item.path;
            const Icon = item.icon;
            return (
              <Link 
                key={item.path} 
                to={item.path}
                className={`flex flex-col items-center justify-center w-16 h-full space-y-1 transition-colors ${
                  isActive ? 'text-primary' : 'text-gray-400'
                }`}
              >
                <Icon size={20} className={isActive ? 'stroke-[2.5px]' : 'stroke-2'} />
                <span className="text-[10px] font-medium">{item.label}</span>
              </Link>
            );
          })}
        </nav>
      )}
    </div>
  );
};

export default Layout;

