  const [showPassword, setShowPassword] = useState(false);
  const [role, setRole] = useState<UserRole>(UserRole.CLIENT);
  const { setUser } = useApp();
  const navigate = useNavigate();

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    // Simple mock auth
    setUser({
      name: role === UserRole.CLIENT ? 'Jean Dupont' : 'Gérant Boutique',
      email,
      points: 125,
      role,
      neighborhood: 'Plateau'
    });
    navigate(role === UserRole.CLIENT ? '/home' : '/dashboard');
  };

  return (
    <div className="flex-1 bg-white p-6 flex flex-col justify-center">
      <div className="mb-10 text-center">
        <h1 className="text-3xl font-bold text-dark mb-2">Bon retour !</h1>
