            role === UserRole.CLIENT ? 'bg-white text-primary shadow-sm' : 'text-gray-500'
          }`}
        >
          <User size={18} className="mr-2" /> Client
        </button>
        <button 
          onClick={() => setRole(UserRole.STORE)}
          className={`flex-1 flex items-center justify-center py-2 rounded-lg font-medium transition-all ${
            role === UserRole.STORE ? 'bg-white text-primary shadow-sm' : 'text-gray-500'
