import { Star, MapPin, Search, Filter } from 'lucide-react';

const StoreList: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredStores = MOCK_STORES.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <Layout title="Toutes les Supérettes" showBack>
      <div className="p-4 space-y-4">
        {/* Search & Filter */}
        <div className="flex space-x-2">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text"
              placeholder="Rechercher une boutique..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-white border border-gray-200 rounded-xl py-2 pl-10 pr-4 text-sm focus:ring-1 focus:ring-primary outline-none"
            />
          </div>
          <button className="bg-white border border-gray-200 p-2 rounded-xl text-gray-500">
            <Filter size={18} />
          </button>
        </div>

        {/* Store Grid */}
        <div className="grid grid-cols-1 gap-4">
          {filteredStores.map(store => (
            <Link 
              key={store.id} 
              to={`/store/${store.id}`}
              className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 flex flex-col group active:scale-[0.99] transition-transform"
            >
              <div className="h-32 relative overflow-hidden">
                <img src={store.image} alt={store.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                <div className="absolute top-3 right-3 bg-white/90 backdrop-blur px-2 py-1 rounded-lg flex items-center shadow-sm">
                  <Star size={12} className="text-accent fill-accent mr-1" />
                  <span className="text-[10px] font-bold text-dark">{store.rating}</span>
                </div>
                <div className="absolute bottom-3 left-3 bg-primary text-white text-[10px] font-bold px-2 py-1 rounded-lg">
                  Ouvert
                </div>
              </div>
              <div className="p-4">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="font-bold text-dark text-lg">{store.name}</h3>
                    <div className="flex items-center text-xs text-gray-500 mt-1">
                      <MapPin size={12} className="mr-1 text-primary" />
                      {store.distance} • {store.neighborhood}
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-[10px] text-gray-400 font-medium">HORAIRES</div>
                    <div className="text-[10px] font-bold text-dark uppercase">{store.hours}</div>
                  </div>
                </div>
              </div>
            </Link>
          ))}
        </div>

        {filteredStores.length === 0 && (
          <div className="text-center py-20">
            <p className="text-gray-400">Aucune boutique trouvée.</p>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default StoreList;

import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import Layout from '../components/Layout';
import { MOCK_STORES, MOCK_PRODUCTS, CATEGORIES } from '../constants';
import { useApp } from '../App';
import { Plus, Info, Globe, MapPin } from 'lucide-react';
import { ProductOrigin } from '../types';

const Catalog: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { addToCart } = useApp();
  const [activeCat, setActiveCat] = useState('all');

  const store = MOCK_STORES.find(s => s.id === id);
  const products = MOCK_PRODUCTS.filter(p => p.storeId === id);

  if (!store) return <Layout showBack>Boutique non trouvée</Layout>;

  return (
    <Layout title={store.name} showBack>
      {/* Store Header Info */}
      <div className="relative h-48">
        <img src={store.image} className="w-full h-full object-cover" alt={store.name} />
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
        <div className="absolute bottom-4 left-4 text-white">
          <div className="flex items-center text-xs opacity-90 mb-1">
            <MapPin size={12} className="mr-1" /> {store.neighborhood}
          </div>
          <h1 className="text-2xl font-bold">{store.name}</h1>
        </div>
      </div>

      <div className="bg-white rounded-t-[32px] -mt-8 relative z-10 px-4 pt-6">
        {/* Catégories horizontal scroll */}
        <div className="flex space-x-3 overflow-x-auto no-scrollbar mb-6 -mx-4 px-4">
          {CATEGORIES.map(cat => (
            <button
              key={cat.id}
              onClick={() => setActiveCat(cat.id)}
              className={`whitespace-nowrap px-4 py-2 rounded-xl text-sm font-bold transition-all ${
                activeCat === cat.id ? 'bg-primary text-white shadow-md' : 'bg-light text-gray-500'
              }`}
            >
              {cat.icon} {cat.name}
            </button>
          ))}
        </div>

        {/* Product Grid */}
        <div className="grid grid-cols-2 gap-4 pb-8">
          {products.map(product => (
            <div key={product.id} className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden flex flex-col">
              <div className="relative h-32">
                <img src={product.image} className="w-full h-full object-cover" alt={product.name} />
                <div className={`absolute top-2 left-2 px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-wider ${
                  product.origin === ProductOrigin.LOCAL ? 'bg-primary text-white' : 'bg-gray-400 text-white'
                }`}>
                  {product.origin === ProductOrigin.LOCAL ? 'PRODUIT LOCAL' : 'IMPORTÉ'}
                </div>
              </div>
              <div className="p-3 flex-1 flex flex-col">
                <h4 className="text-sm font-bold text-dark line-clamp-2 h-10">{product.name}</h4>
                <p className="text-[10px] text-gray-400 mt-1 uppercase font-bold tracking-tighter">{product.category}</p>
                <div className="flex items-center justify-between mt-auto pt-3">
                  <div className="flex flex-col">
                    <span className="text-primary font-bold text-sm">{product.price.toLocaleString('fr-FR')} FCFA</span>
                  </div>
                  <button 
                    onClick={() => addToCart(product)}
                    className="bg-primary text-white p-2 rounded-xl active:scale-90 transition-transform shadow-sm"
                  >
                    <Plus size={18} />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </Layout>
  );
};

export default Catalog;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { useApp } from '../App';
import { Minus, Plus, Trash2, ShoppingBag, CreditCard } from 'lucide-react';

const Cart: React.FC = () => {
  const { cart, updateQuantity, removeFromCart, placeOrder } = useApp();
  const navigate = useNavigate();

  const subtotal = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
  const deliveryFee = cart.length > 0 ? 500 : 0;
  const total = subtotal + deliveryFee;
  const points = Math.floor(subtotal / 100);

  return (
    <Layout title="Mon Panier" showBack>
