import React, { useState, useEffect, createContext, useContext } from 'react';
import { Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import { UserRole, UserProfile, CartItem, Product, Store, Order } from './types';
import { MOCK_STORES, MOCK_PRODUCTS } from './constants';

// Context for global state
interface AppContextType {
  user: UserProfile | null;
  setUser: (user: UserProfile | null) => void;
  cart: CartItem[];
  addToCart: (product: Product) => void;
  removeFromCart: (productId: string) => void;
  updateQuantity: (productId: string, delta: number) => void;
  clearCart: () => void;
  orders: Order[];
  placeOrder: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

// Pages
import Splash from './pages/Splash';
import Onboarding from './pages/Onboarding';
import Login from './pages/Login';
import Home from './pages/Home';
import StoreList from './pages/StoreList';
import Catalog from './pages/Catalog';
import Cart from './pages/Cart';
import Fidelity from './pages/Fidelity';
import Profile from './pages/Profile';
import Dashboard from './pages/Dashboard';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const navigate = useNavigate();
  const location = useLocation();

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const clearCart = () => setCart([]);

  const placeOrder = () => {
    if (cart.length === 0) return;
    const total = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
    const points = Math.floor(total / 100);

    const newOrder: Order = {
      id: `ORD-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      date: new Date().toLocaleDateString('fr-FR'),
      total,
      status: 'PENDING',
      items: [...cart],
      pointsGained: points
    };

    setOrders(prev => [newOrder, ...prev]);
    if (user) {
      setUser({ ...user, points: user.points + points });
    }
    clearCart();
    navigate('/fidelity');
  };

  useEffect(() => {
    const publicPaths = ['/', '/onboarding', '/login'];
    if (!user && !publicPaths.includes(location.pathname)) {
      navigate('/login');
    }
    if (user && user.role === UserRole.STORE && location.pathname === '/home') {
      navigate('/dashboard');
    }
  }, [user, location.pathname, navigate]);

  return (
    <AppContext.Provider value={{
      user, setUser, cart, addToCart, removeFromCart, updateQuantity, clearCart, orders, placeOrder
    }}>
      <div className="w-full min-h-screen bg-white md:bg-gray-50 flex flex-col items-center">
        {/* Container principal qui se centre sur desktop */}
        <div className="w-full md:max-w-7xl md:min-h-screen bg-white md:shadow-2xl md:my-0 flex flex-col relative overflow-hidden">
          <Routes>
            <Route path="/" element={<Splash />} />
            <Route path="/onboarding" element={<Onboarding />} />
            <Route path="/login" element={<Login />} />
            <Route path="/home" element={<Home />} />
            <Route path="/stores" element={<StoreList />} />
            <Route path="/store/:id" element={<Catalog />} />
            <Route path="/cart" element={<Cart />} />
            <Route path="/fidelity" element={<Fidelity />} />
            <Route path="/profile" element={<Profile />} />
            <Route path="/dashboard" element={<Dashboard />} />
          </Routes>
        </div>
      </div>
    </AppContext.Provider>
  );
};

export default App;

