import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { useApp } from '../App';
import { Minus, Plus, Trash2, ShoppingBag, CreditCard, MapPin, ChevronDown } from 'lucide-react';
import { Address } from '../types';

const Cart: React.FC = () => {
  const { cart, updateQuantity, removeFromCart, placeOrder, user } = useApp();
  const [selectedAddress, setSelectedAddress] = useState<Address | null>(user?.addresses[0] || null);
  const [showAddressPicker, setShowAddressPicker] = useState(false);
  const navigate = useNavigate();

  const subtotal = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
  const deliveryFee = cart.length > 0 ? 150 : 0;
  const total = subtotal + deliveryFee;

  const handleCheckout = () => {
    if (!selectedAddress && user?.addresses[0]) {
      placeOrder(user.addresses[0]);
    } else if (selectedAddress) {
      placeOrder(selectedAddress);
    } else {
      // Create a default if none exists for demo
      placeOrder({ id: '1', label: 'Défaut', details: 'Quartier principal', wilaya: 'Alger', neighborhood: 'Hydra' });
    }
  };

  return (
    <Layout title="Mon Panier" showBack>
      <div className="p-4 md:p-12 space-y-8">
        {cart.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-24 text-center">
            <ShoppingBag size={80} className="opacity-10 mb-8" />
            <h3 className="text-2xl font-black">Panier vide</h3>
            <button onClick={() => navigate('/home')} className="mt-8 bg-primary text-white px-10 py-4 rounded-2xl font-black uppercase text-xs tracking-widest">Faire mes courses</button>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
            <div className="lg:col-span-2 space-y-4">
              <h3 className="text-sm font-black uppercase opacity-40 px-2 tracking-widest">Mes Articles</h3>
              {cart.map(item => (
                <div key={item.id} className={`p-4 md:p-6 rounded-[32px] border flex items-center space-x-6 ${user?.theme === 'dark' ? 'bg-white/5 border-white/5' : 'bg-white border-gray-100'}`}>
                  <img src={item.image} className="w-20 h-20 md:w-24 md:h-24 rounded-2xl object-cover" />
                  <div className="flex-1">
                    <h4 className="font-bold text-sm md:text-lg">{item.name}</h4>
                    <span className="text-primary font-black">{item.price} DA</span>
                  </div>
                  <div className="flex items-center bg-gray-100 dark:bg-white/5 p-2 rounded-xl space-x-4">
                    <button onClick={() => updateQuantity(item.id, -1)} className="p-2 hover:text-primary"><Minus size={16} /></button>
                    <span className="font-black w-4 text-center text-sm">{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.id, 1)} className="p-2 hover:text-primary"><Plus size={16} /></button>
                  </div>
                  <button onClick={() => removeFromCart(item.id)} className="text-error opacity-40 hover:opacity-100"><Trash2 size={20} /></button>
                </div>
              ))}
            </div>

            <aside className="space-y-6">
              <div className={`p-8 rounded-[40px] border ${user?.theme === 'dark' ? 'bg-white/5 border-white/5' : 'bg-white border-gray-100'}`}>
                <h3 className="text-xl font-black mb-8">Résumé</h3>

                <div className="space-y-4 mb-8">
                  <div className="flex justify-between text-sm opacity-50"><span>Articles</span><span>{subtotal.toLocaleString()} DA</span></div>
                  <div className="flex justify-between text-sm opacity-50"><span>Livraison</span><span>{deliveryFee} DA</span></div>
                  <div className="pt-4 border-t border-dashed border-white/10 flex justify-between items-center">
                    <span className="font-black uppercase text-xs">Total</span>
                    <span className="text-3xl font-black text-primary">{total.toLocaleString()} DA</span>
                  </div>
                </div>

                <div className="mb-10">
                  <label className="text-[10px] font-black uppercase opacity-40 mb-3 block">Lieu de livraison</label>
                  <button className="w-full flex items-center justify-between p-4 bg-gray-100 dark:bg-white/5 rounded-2xl text-xs font-bold text-left">
                    <div className="flex items-center">
                      <MapPin size={16} className="text-primary mr-3" />
                      <span>{selectedAddress?.label || "Sélectionner une adresse"}</span>
                    </div>
                    <ChevronDown size={16} />
                  </button>
                </div>

                <button onClick={handleCheckout} className="w-full bg-primary text-white py-5 rounded-[22px] font-black uppercase text-xs tracking-[0.2em] shadow-2xl shadow-primary/30 flex items-center justify-center">
                   <CreditCard size={18} className="mr-3" /> Payer à la livraison
                </button>
              </div>

              <div className="bg-primary/10 p-6 rounded-[32px] text-center">
                 <p className="text-[10px] font-black uppercase tracking-widest text-primary">Gains Fidélité</p>
                 <div className="text-2xl font-black text-primary mt-1">+{Math.floor(subtotal / 100)} pts</div>
              </div>
            </aside>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default Cart;

import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import Layout from '../components/Layout';
import { MOCK_STORES, MOCK_PRODUCTS, CATEGORIES } from '../constants';
import { useApp } from '../App';
import { Plus, MapPin, Star, Phone, MessageCircle } from 'lucide-react';
import { ProductOrigin } from '../types';

const Catalog: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { addToCart, user } = useApp();
  const [activeCat, setActiveCat] = useState('all');
  const [showLocalOnly, setShowLocalOnly] = useState(false);
  const isDark = user?.theme === 'dark';

  const store = MOCK_STORES.find(s => s.id === id);
  let products = MOCK_PRODUCTS.filter(p => p.storeId === id);

  if (activeCat !== 'all') products = products.filter(p => p.category === activeCat);
  if (showLocalOnly) products = products.filter(p => p.origin === ProductOrigin.LOCAL);

  if (!store) return <Layout showBack>Boutique non trouvée</Layout>;

  return (
    <Layout title={store.name} showBack>
      <div className="relative h-64 md:h-96">
        <img src={store.image} className="w-full h-full object-cover" alt={store.name} />
        <div className="absolute inset-0 bg-gradient-to-t from-dark to-transparent opacity-80"></div>
        <div className="absolute bottom-8 left-4 md:left-12 text-white">
          <h1 className="text-3xl md:text-6xl font-black uppercase mb-2">{store.name}</h1>
          <div className="flex items-center space-x-4 text-[10px] font-black uppercase tracking-widest">
            <span className="flex items-center"><MapPin size={12} className="mr-1.5" /> {store.neighborhood}</span>
            <span className="flex items-center text-accent"><Star size={12} className="mr-1.5 fill-current" /> {store.rating}</span>
          </div>
        </div>
        <div className="absolute top-4 right-4 flex space-x-2">
           <a href={`tel:${store.phone}`} className="p-3 bg-white/10 backdrop-blur rounded-2xl text-white hover:bg-white/20"><Phone size={20}/></a>
           <button className="p-3 bg-white/10 backdrop-blur rounded-2xl text-white hover:bg-white/20"><MessageCircle size={20}/></button>
        </div>
      </div>

      <div className={`p-4 md:p-12 space-y-10 ${isDark ? 'bg-[#121212]' : 'bg-white'} rounded-t-[40px] -mt-10 relative z-10`}>
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex space-x-3 overflow-x-auto no-scrollbar pb-2">
            {CATEGORIES.map(cat => (
              <button key={cat.id} onClick={() => setActiveCat(cat.id)} className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeCat === cat.id ? 'bg-primary text-white' : 'bg-gray-100 dark:bg-white/5'}`}>
                {user?.lang === 'ar' ? cat.nameAr : cat.name}
              </button>
            ))}
          </div>
          <button onClick={() => setShowLocalOnly(!showLocalOnly)} className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${showLocalOnly ? 'bg-primary border-primary text-white' : 'border-primary text-primary'}`}>
            Filtre Terroir 🇩🇿
          </button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-6">
          {products.map(p => (
            <div key={p.id} className={`group rounded-[32px] border overflow-hidden transition-all hover:shadow-2xl ${isDark ? 'bg-white/5 border-white/5' : 'bg-white border-gray-100'}`}>
              <div className="relative aspect-square overflow-hidden">
                <img src={p.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                {p.stock <= 5 && p.stock > 0 && <span className="absolute top-2 right-2 bg-orange-500 text-white text-[8px] px-2 py-1 rounded-lg font-black">STOCK BAS</span>}
                {p.stock === 0 && <div className="absolute inset-0 bg-dark/60 flex items-center justify-center text-white text-[10px] font-black uppercase">Épuisé</div>}
              </div>
              <div className="p-5">
                <div className="text-[8px] opacity-40 font-black uppercase tracking-widest">{p.category}</div>
                <h4 className="font-bold text-sm h-10 line-clamp-2 mt-1">{p.name}</h4>
                <div className="mt-4 flex items-center justify-between">
                  <span className="font-black text-primary">{p.price} DA</span>
                  <button 
                    disabled={p.stock === 0}
                    onClick={() => addToCart(p)} 
                    className={`p-2 rounded-xl transition-all ${p.stock === 0 ? 'bg-gray-200 text-gray-400' : 'bg-primary text-white shadow-lg active:scale-90'}`}>
                    <Plus size={18} />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </Layout>
  );
};

export default Catalog;

