export enum UserRole {
  CLIENT = 'CLIENT',
  STORE = 'STORE',
  ADMIN = 'ADMIN'
}

export enum ProductOrigin {
  LOCAL = 'LOCAL',
  IMPORTED = 'IMPORTED'
}

export interface Product {
  id: string;
  name: string;
  price: number;
  origin: ProductOrigin;
  category: string;
  image: string;
  stock: number;
  storeId: string;
}

export interface Store {
  id: string;
  name: string;
  distance: string;
  rating: number;
  hours: string;
  image: string;
  wilaya: string;
  neighborhood: string;
  description?: string;
  phone?: string;
  lat?: number;
  lng?: number;
}

export interface Address {
  id: string;
  label: string; // "Maison", "Travail", etc.
  details: string;
  wilaya: string;
  neighborhood: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export type OrderStatus = 'PENDING' | 'PREPARING' | 'PICKUP' | 'DELIVERING' | 'COMPLETED' | 'CANCELLED';

export interface Order {
  id: string;
  date: string;
  total: number;
  status: OrderStatus;
  items: CartItem[];
  pointsGained: number;
  storeName?: string;
  address?: Address;
}

export interface UserProfile {
  name: string;
  email: string;
  points: number;
  role: UserRole;
  wilaya: string;
  neighborhood: string;
  lang: 'fr' | 'ar';
  theme: 'light' | 'dark';
  addresses: Address[];
}

export interface Notification {
  id: string;
  title: string;
  message: string;
  time: string;
  read: boolean;
  type: 'PROMO' | 'ORDER' | 'SYSTEM';
}

