import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import Layout from '../components/Layout';
import { MOCK_STORES, ALGERIA_GEOGRAPHY } from '../constants';
import { Star, MapPin, Search, Filter, Navigation } from 'lucide-react';
import { useApp } from '../App';

const StoreList: React.FC = () => {
  const { user } = useApp();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedWilaya, setSelectedWilaya] = useState(user?.wilaya || '');
  const [selectedNeighborhood, setSelectedNeighborhood] = useState(user?.neighborhood || '');
  const [isLocating, setIsLocating] = useState(false);

  const filteredStores = MOCK_STORES.filter(s => {
    const matchesSearch = s.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesWilaya = selectedWilaya === '' || s.wilaya === selectedWilaya;
    const matchesNeighborhood = selectedNeighborhood === '' || s.neighborhood === selectedNeighborhood;
    return matchesSearch && matchesWilaya && matchesNeighborhood;
  });

  const handleFindNearby = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((position) => {
        // Dans une vraie app, on utiliserait le reverse geocoding pour trouver la wilaya/quartier
        // Ici on simule en disant qu'on a trouvé le quartier de l'utilisateur
        setTimeout(() => {
          setSelectedWilaya(user?.wilaya || 'Alger');
          setSelectedNeighborhood(user?.neighborhood || 'Hydra');
          setIsLocating(false);
          alert("Géolocalisation réussie : Recherche dans votre quartier actuel.");
        }, 1500);
      }, (error) => {
        setIsLocating(false);
        alert("Impossible de récupérer votre position. Vérifiez vos permissions.");
      });
    } else {
      setIsLocating(false);
      alert("La géolocalisation n'est pas supportée par votre navigateur.");
    }
  };

  return (
    <Layout title="Toutes les Supérettes" showBack>
      <div className="p-4 md:p-12 space-y-8 pb-32">
        {/* Header Section */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
