            <h2 className="text-3xl font-black uppercase tracking-tight">Trouver une boutique</h2>
            <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1">
              {filteredStores.length} boutiques disponibles dans la zone sélectionnée
            </p>
          </div>
          <button 
            onClick={handleFindNearby}
            disabled={isLocating}
            className={`flex items-center space-x-3 px-6 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest transition-all ${
              isLocating ? 'bg-gray-100 text-gray-400' : 'bg-primary/10 text-primary hover:bg-primary/20'
            }`}
          >
            <Navigation size={16} className={isLocating ? 'animate-spin' : ''} />
            <span>{isLocating ? 'Localisation...' : 'Trouver autour de moi'}</span>
          </button>
        </div>

        {/* Filters Panel */}
        <div className="bg-white dark:bg-white/5 rounded-[32px] p-6 border border-gray-100 dark:border-white/5 shadow-sm space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text"
                placeholder="Nom de la boutique..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-50 dark:bg-white/5 border-none rounded-2xl py-4 pl-12 pr-4 text-sm font-bold focus:ring-2 focus:ring-primary outline-none transition-all"
              />
            </div>

            <select 
              value={selectedWilaya}
              onChange={(e) => {
                setSelectedWilaya(e.target.value);
                setSelectedNeighborhood('');
              }}
              className="w-full bg-gray-50 dark:bg-white/5 border-none rounded-2xl py-4 px-6 text-sm font-bold focus:ring-2 focus:ring-primary outline-none transition-all appearance-none"
            >
              <option value="">Toutes les Wilayas</option>
              {ALGERIA_GEOGRAPHY.map(g => (
                <option key={g.wilaya} value={g.wilaya}>{g.wilaya}</option>
              ))}
            </select>

            <select 
              value={selectedNeighborhood}
              onChange={(e) => setSelectedNeighborhood(e.target.value)}
