            <div className="relative">
              <button onClick={() => setShowNotifs(!showNotifs)} className={`p-2 rounded-xl transition-all ${showNotifs ? 'bg-primary text-white' : isDark ? 'bg-white/5 text-white' : 'bg-gray-100 text-dark'}`}>
