          {isClient && (
            <Link to="/cart" className="relative p-2.5 bg-primary text-white rounded-xl shadow-lg shadow-primary/20">
              <ShoppingCart size={20} />
              {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-white text-primary text-[10px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-primary">{cart.length}</span>}
            </Link>
          )}
