      </header>

      <main className="flex-1 overflow-y-auto no-scrollbar pb-24 md:pb-8">
        <div className="max-w-7xl mx-auto w-full">{children}</div>
      </main>

      {!hideNav && (
        <nav className={`md:hidden sticky bottom-0 z-[60] flex items-center justify-around h-18 px-2 border-t backdrop-blur-xl ${isDark ? 'bg-[#121212]/90 border-white/5' : 'bg-white/90 border-gray-100'}`}>
          {navItems.map((item) => {
            const isActive = location.pathname === item.path;
            const Icon = item.icon;
            return (
              <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full transition-all ${isActive ? 'text-primary' : 'text-gray-400'}`}>
                <Icon size={isActive ? 24 : 22} className={isActive ? 'stroke-[2.5px]' : ''} />
              </Link>
            );
          })}
        </nav>
      )}
    </div>
  );
};

