import React, { useState, useEffect, createContext, useContext } from 'react';
import { Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import { UserRole, UserProfile, CartItem, Product, Store, Order, Notification, Address } from './types';
import { MOCK_STORES, MOCK_PRODUCTS, MOCK_NOTIFICATIONS } from './constants';

interface AppContextType {
  user: UserProfile | null;
  setUser: (user: UserProfile | null) => void;
  cart: CartItem[];
  addToCart: (product: Product) => void;
  removeFromCart: (productId: string) => void;
  updateQuantity: (productId: string, delta: number) => void;
  clearCart: () => void;
  orders: Order[];
  placeOrder: (address: Address) => void;
  notifications: Notification[];
  markAsRead: (id: string) => void;
  toggleTheme: () => void;
  toggleLang: () => void;
  installPrompt: any;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

// Pages
import Splash from './pages/Splash';
import Onboarding from './pages/Onboarding';
import Login from './pages/Login';
import Home from './pages/Home';
import StoreList from './pages/StoreList';
import Catalog from './pages/Catalog';
import Cart from './pages/Cart';
import Fidelity from './pages/Fidelity';
import Profile from './pages/Profile';
import Dashboard from './pages/Dashboard';

const App: React.FC = () => {
  // Initialisation des états depuis le localStorage pour simuler une DB
  const [user, setUserState] = useState<UserProfile | null>(() => {
    const saved = localStorage.getItem('hoomty_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('hoomty_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const saved = localStorage.getItem('hoomty_orders');
    return saved ? JSON.parse(saved) : [];
  });

  const [notifications, setNotifications] = useState<Notification[]>(() => {
    const saved = localStorage.getItem('hoomty_notifications');
    return saved ? JSON.parse(saved) : MOCK_NOTIFICATIONS;
  });

  const [installPrompt, setInstallPrompt] = useState<any>(null);
  const navigate = useNavigate();
  const location = useLocation();

  // Wrapper pour setUser qui sauvegarde aussi dans localStorage
  const setUser = (newUser: UserProfile | null) => {
    setUserState(newUser);
    if (newUser) {
      localStorage.setItem('hoomty_user', JSON.stringify(newUser));
    } else {
      localStorage.removeItem('hoomty_user');
      localStorage.removeItem('hoomty_cart');
      localStorage.removeItem('hoomty_orders');
    }
  };

  // Sauvegarde automatique du panier et des commandes
  useEffect(() => {
    localStorage.setItem('hoomty_cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('hoomty_orders', JSON.stringify(orders));
  }, [orders]);

  useEffect(() => {
    localStorage.setItem('hoomty_notifications', JSON.stringify(notifications));
  }, [notifications]);

  // Gestion de l'installation PWA
  useEffect(() => {
    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.id !== productId));
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === productId) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const clearCart = () => setCart([]);

  const markAsRead = (id: string) => {
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const toggleTheme = () => {
    if (user) {
      const updatedUser: UserProfile = { ...user, theme: user.theme === 'light' ? 'dark' : 'light' };
      setUser(updatedUser);
      // Appliquer la classe dark au document pour Tailwind
      if (updatedUser.theme === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
  };

  useEffect(() => {
    if (user?.theme === 'dark') {
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleLang = () => {
    if (user) setUser({ ...user, lang: user.lang === 'fr' ? 'ar' : 'fr' });
  };

  const placeOrder = (address: Address) => {
    if (cart.length === 0) return;
    const total = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
    const points = Math.floor(total / 100);

    const newOrder: Order = {
      id: `ORD-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      date: new Date().toLocaleDateString('fr-FR'),
      total,
      status: 'PENDING',
      items: [...cart],
      pointsGained: points,
      address,
      storeName: cart[0].storeId === 's1' ? 'Hoomty Market El Mordjane' : 'Supérette La Famille'
    };

    setOrders(prev => [newOrder, ...prev]);
    if (user) setUser({ ...user, points: user.points + points });
    clearCart();
    navigate('/fidelity');
  };

  useEffect(() => {
    const publicPaths = ['/', '/onboarding', '/login'];
    if (!user && !publicPaths.includes(location.pathname)) {
      navigate('/login');
    }
    if (user && user.role === UserRole.STORE && location.pathname === '/home') {
      navigate('/dashboard');
    }
  }, [user, location.pathname, navigate]);

  return (
    <AppContext.Provider value={{
      user, setUser, cart, addToCart, removeFromCart, updateQuantity, clearCart, orders, placeOrder, notifications, markAsRead, toggleTheme, toggleLang, installPrompt
    }}>
      <div className={`w-full min-h-screen flex flex-col items-center transition-colors duration-300 ${user?.theme === 'dark' ? 'bg-[#0a0a0a]' : 'bg-gray-50'}`}>
        <div className={`w-full md:max-w-7xl md:min-h-screen flex flex-col relative overflow-hidden shadow-2xl ${user?.theme === 'dark' ? 'bg-[#121212] text-white' : 'bg-white'}`}>
          <Routes>
            <Route path="/" element={<Splash />} />
            <Route path="/onboarding" element={<Onboarding />} />
            <Route path="/login" element={<Login />} />
            <Route path="/home" element={<Home />} />
            <Route path="/stores" element={<StoreList />} />
            <Route path="/store/:id" element={<Catalog />} />
            <Route path="/cart" element={<Cart />} />
            <Route path="/fidelity" element={<Fidelity />} />
            <Route path="/profile" element={<Profile />} />
            <Route path="/dashboard" element={<Dashboard />} />
          </Routes>
        </div>
      </div>
    </AppContext.Provider>
  );
};

export default App;

export enum UserRole {
  CLIENT = 'CLIENT',
  STORE = 'STORE',
  ADMIN = 'ADMIN'
}

export enum ProductOrigin {
  LOCAL = 'LOCAL',
  IMPORTED = 'IMPORTED'
}

export interface Product {
  id: string;
  name: string;
  price: number;
  origin: ProductOrigin;
  category: string;
  image: string;
  stock: number;
  storeId: string;
}

export interface Store {
  id: string;
  name: string;
  distance: string;
  rating: number;
  hours: string;
  image: string;
  wilaya: string;
  neighborhood: string;
  description?: string;
  phone?: string;
  lat?: number;
  lng?: number;
}

export interface Address {
  id: string;
  label: string;
  details: string;
  wilaya: string;
  neighborhood: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export type OrderStatus = 'PENDING' | 'PREPARING' | 'PICKUP' | 'DELIVERING' | 'COMPLETED' | 'CANCELLED';

export interface Order {
  id: string;
  date: string;
  total: number;
  status: OrderStatus;
  items: CartItem[];
  pointsGained: number;
  storeName?: string;
  address?: Address;
}

export interface UserProfile {
  name: string;
  pseudonym: string;
  email: string;
  points: number;
  role: UserRole;
  wilaya: string;
  neighborhood: string;
  lang: 'fr' | 'ar';
  theme: 'light' | 'dark';
  addresses: Address[];
}

export interface Notification {
  id: string;
  title: string;
  message: string;
  time: string;
  read: boolean;
  type: 'PROMO' | 'ORDER' | 'SYSTEM';
}

