                </div>

                <button onClick={handleCheckout} className="w-full bg-primary text-white py-5 rounded-[22px] font-black uppercase text-xs tracking-[0.2em] shadow-2xl shadow-primary/30 flex items-center justify-center hover:scale-[1.02] active:scale-95 transition-all">
                   <CreditCard size={18} className="mr-3" /> Confirmer & Payer Cash
