      {!hideNav && (
        <nav className="md:hidden sticky bottom-0 z-[60] px-6 pb-6 pt-2">
          <div className="flex items-center justify-around h-16 bg-slate-950/90 dark:bg-white/90 backdrop-blur-xl rounded-[28px] shadow-2xl border border-white/10">
            {navItems.map((item) => {
              const isActive = location.pathname === item.path;
