              return (
                <Link key={item.path} to={item.path} className={`flex flex-col items-center justify-center w-full transition-all ${isActive ? 'text-primary' : 'text-gray-500'}`}>
                  <div className={`p-2 rounded-xl transition-all ${isActive ? 'bg-primary/10 text-primary' : ''}`}>
                    <Icon size={24} className={isActive ? 'stroke-[2.5px]' : ''} />
                  </div>
                </Link>
              );
            })}
          </div>
        </nav>
      )}
    </div>
  );
};

